mapper.select:
select cr_rb_room.resource_id, cr_rb_room.template_id template, cr_rb_room.template_name, cr_rb_room.`NAME`, cr_rb_room.description, cr_rb_room.sub_type category, cr_rb_room.pre_skill, cr_rb_room.train_skill, cr_rb_room.start_time, cr_rb_room.end_time, cr_rb_room.difficulty difficult, cr_rb_room.create_user_id, cr_rb_room.modify_user_id, cr_rb_room.local_scene_id, cr_rb_room.copyed_topo_id, cr_rb_room.training_status, cr_rb_template.duration_time, cr_rb_template.business_template_id, local_scene.start_time scene_start_time, local_scene.end_time scene_end_time, local_scene.scene_status, ( CASE
WHEN cr_rb_room.training_status = 4 THEN 2 WHEN cr_rb_room.training_status = 2 THEN 1 WHEN cr_rb_room.training_status = 1 THEN 1 WHEN cr_rb_room.training_status = 3 THEN 1 WHEN cr_rb_room.training_status = 0 THEN 3 END ) order_status from cr_rb_room left join cr_rb_template on cr_rb_room.template_id = cr_rb_template.resource_id left join local_scene on cr_rb_room.resource_id = local_scene.business_instance_id
cr_rb_room.resource_id in
#{roomId}
('')
and cr_rb_room.name like #{search}
and cr_rb_room.difficulty = #{listQuery.difficult}
and cr_rb_room.name = #{listQuery.name}
and cr_rb_room.sub_type = #{listQuery.category}
ORDER BY order_status

select date_format(end_time, '%y-%m-%d') as `date`, sum(case when training_status = 0 then 1 else 0 end) as completed from cr_rb_room where date_format(end_time, '%y-%m-%d') >= DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 10 DAY),'%y-%m-%d') AND date_format(end_time, '%y-%m-%d') <= date_format(NOW(), '%y-%m-%d')
and resource_id in
#{roomId}
group by date_format(end_time, '%y-%m-%d');

select *
from cr_rb_room
where training_status != #{endStatus}
and resource_id
in

    #{roomId}
